175→    onClose();
176→  };
177→
178→  const handleShare = () => {
179→    onShare?.();
180→    onClose();
181→  };
182→
183→  const handleDelete = () => {
184→    onDelete();
185→    onClose();
186→  };
187→
188→  const handleDetails = () => {
189→    onDetails();
190→    onClose();
191→  };
192→
193→  const handleBatchDownload = () => {
194→    onBatchDownload?.();
195→    onClose();
196→  };
197→
198→  const handleBatchMove = () => {
199→    onBatchMove?.();
200→    onClose();
201→  };
202→
203→  const handleBatchDelete = () => {
204→    onBatchDelete?.();
205→    onClose();
