```typescript
import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import { FileBrowserPage } from '../pages/FileBrowserPage';
import { BinPage } from '../pages/BinPage';

test.describe('Recycle Bin', () => {
  let loginPage: LoginPage;
  let fileBrowser: FileBrowserPage;
  let binPage: BinPage;

  test.beforeEach(async ({ page }) => {
    loginPage = new LoginPage(page);
    fileBrowser = new FileBrowserPage(page);
    binPage = new BinPage(page);
    await loginPage.login();
  });

  test('TC01: Delete file moves to bin', async ({ page }) => {
    // Upload a test file
    const fileName = `test-bin-${Date.now()}.txt`;
    await fileBrowser.uploadFile(fileName, 'Test content for bin');

    // Delete the file
    await fileBrowser.deleteFile(fileName);

    // Verify file is gone from files
    await expect(page.getByText(fileName)).not.toBeVisible();

    // Navigate to bin
    await binPage.navigate();

    // Wait for bin to load and verify file is in bin
    const binItem = await binPage.getBinItemByName(fileName);
    await expect(binItem).toBeVisible();
  });

  test('TC02: Restore file from bin', async ({ page }) => {
    // Upload and delete a test file
    const fileName = `test-restore-${Date.now()}.txt`;
    await fileBrowser.uploadFile(fileName, 'Restore test content');
    await fileBrowser.deleteFile(fileName);

    // Navigate to bin and restore
    await binPage.navigate();
    await binPage.restoreItem(fileName);

    // Wait for restore to complete
    await page.waitForTimeout(2000); // Allow IPNS publish

    // Navigate back to files
    await page.getByTestId('nav-item-files').click();

    // Verify file is back
    await expect(page.getByText(fileName)).toBeVisible();
  });

  test('TC03: Permanently delete from bin', async ({ page }) => {
    // Upload and delete a test file
    const fileName = `test-perma-${Date.now()}.txt`;
    await fileBrowser.uploadFile(fileName, 'Permanent delete test');
    await fileBrowser.deleteFile(fileName);

    // Navigate to bin
    await binPage.navigate();
    const binItem = await binPage.getBinItemByName(fileName);
    await expect(binItem).toBeVisible();

    // Permanently delete
    await binPage.permanentlyDeleteItem(fileName);

    // Verify item is gone from bin
    await expect(binItem).not.toBeVisible();
  });

  test('TC04: Empty bin removes all items', async ({ page }) => {
    // Upload and delete two test files
    const file1 = `test-empty1-${Date.now()}.txt`;
    const file2 = `test-empty2-${Date.now()}.txt`;
    await fileBrowser.uploadFile(file1, 'Empty test 1');
    await fileBrowser.uploadFile(file2, 'Empty test 2');
    await fileBrowser.deleteFile(file1);
    await fileBrowser.deleteFile(file2);

    // Navigate to bin
    await binPage.navigate();

    // Verify both items in bin
    await expect(await binPage.getBinItemByName(file1)).toBeVisible();
    await expect(await binPage.getBinItemByName(file2)).toBeVisible();

    // Empty bin
    await binPage.emptyBin();

    // Verify bin is empty
    await expect(binPage.emptyState).toBeVisible();
  });

  test('TC05: Bin item shows metadata', async ({ page }) => {
    // Upload and delete a file
    const fileName = `test-meta-${Date.now()}.txt`;
    await fileBrowser.uploadFile(fileName, 'Metadata test content');
    await fileBrowser.deleteFile(fileName);

    // Navigate to bin
    await binPage.navigate();

    // Verify metadata is displayed
    const binItem = await binPage.getBinItemByName(fileName);
    await expect(binItem).toContainText(fileName); // Name
    await expect(binItem).toContainText('day'); // Days remaining text
  });

  test('TC06: Bin sidebar navigation works', async ({ page }) => {
    // Click bin nav item
    await binPage.navigate();

    // Verify we're on the bin page
    expect(page.url()).toContain('#/bin');

    // Bin nav item should be active
    await expect(binPage.binNavItem).toHaveClass(/active/);
  });
});
```

