131→    let event_payload = serde_json::json!({
132→        "itemType": "folder",
133→        "name": name_str,
134→        "folderIpnsName": folder_ipns_name,
135→        "parentIpnsName": parent_ipns_name,
136→    });
137→    let _ = app_handle.emit("bin-soft-delete", event_payload);
